def trace(input_data):
    sess = TraceSession(
        algorithm='House Robber (DP Array)',
        input_data=input_data,
        pseudocode=[
            'Initialize dp array of size n+1',
            'dp[1] = nums[0] (first house)',
            'For i from 2 to n: dp[i] = max(dp[i-1], dp[i-2] + nums[i-1])',
            'Return dp[n]'
        ],
    )
    nums = input_data['nums']
    n = len(nums)
    if n == 0:
        sess.result(0)
        trace = sess.to_trace()
        for event in trace['events']:
            event['code_line'] = 5
        return trace

    arr = sess.array('nums', nums)
    dp = sess.array('dp', [0] * (n + 1))
    dp[1] = nums[0]
    with sess.step('Initialize'):
        arr.highlight(0, role='current')

    for i in range(2, n + 1):
        with sess.step(f'House {i-1}'):
            arr.highlight(i-1, role='selected')
            val1 = dp[i-1]
            val2 = dp[i-2] + nums[i-1]
            if val2 > val1:
                best = val2
                sess.note(f'Rob house {i-1} (+{nums[i-1]}), skip previous')
            else:
                best = val1
                sess.note(f'Skip house {i-1}, keep dp[{i-1}]')
            dp[i] = best

    answer = dp[n]
    sess.result(answer)

    trace = sess.to_trace()
    for event in trace['events']:
        op = event.get('op')
        targets = event.get('targets', [])
        target_ids = [t.get('id', '') for t in targets]
        if op == 'create' and 'nums' in target_ids:
            event['code_line'] = 2
        elif op == 'create' and 'dp' in target_ids:
            event['code_line'] = 6
        elif op == 'set' and 'dp' in target_ids:
            index = targets[0].get('index') if targets else None
            if index == 1:
                event['code_line'] = 7
            else:
                event['code_line'] = 9
        elif op == 'highlight':
            if any('arr' in tid or 'nums' in tid for tid in target_ids):
                event['code_line'] = 9
        elif op == 'note':
            event['code_line'] = 9
        elif op == 'result':
            event['code_line'] = 10
        else:
            event['code_line'] = 9
    return trace

def trace(input_data):
    sess = TraceSession(
        algorithm='House Robber (Two Variables)',
        input_data=input_data,
        pseudocode=[
            'Initialize prev2 = 0, prev1 = nums[0]',
            'For each next house i (1‑based):',
            '  curr = max(prev1, prev2 + nums[i])',
            '  prev2 = prev1; prev1 = curr',
            'Return prev1'
        ],
    )
    nums = input_data['nums']
    n = len(nums)
    if n == 0:
        sess.result(0)
        trace = sess.to_trace()
        for event in trace['events']:
            event['code_line'] = 5
        return trace
    if n == 1:
        sess.result(nums[0])
        trace = sess.to_trace()
        for event in trace['events']:
            event['code_line'] = 7
        return trace

    arr = sess.array('nums', nums)
    prev2 = sess.scalar('prev2', 0)
    prev1 = sess.scalar('prev1', nums[0])

    with sess.step('Start'):
        arr.highlight(0, role='current')

    for i in range(1, n):
        with sess.step(f'House {i}'):
            arr.highlight(i, role='selected')
            if prev1.value > prev2.value + nums[i]:
                curr = prev1.value
                sess.note(f'Skip house {i}, keep prev1={prev1.value}')
            else:
                curr = prev2.value + nums[i]
                sess.note(f'Rob house {i} (+{nums[i]}), total {curr}')
            prev2.set(prev1.value, reason='prev2 moves forward')
            prev1.set(curr, reason='prev1 becomes current best')

    answer = prev1.value
    sess.result(answer)

    trace = sess.to_trace()
    for event in trace['events']:
        op = event.get('op')
        targets = event.get('targets', [])
        target_ids = [t.get('id', '') for t in targets]
        if op == 'create' and 'nums' in target_ids:
            event['code_line'] = 2
        elif op == 'create' and 'prev2' in target_ids:
            event['code_line'] = 8
        elif op == 'create' and 'prev1' in target_ids:
            event['code_line'] = 9
        elif op == 'highlight':
            if any('arr' in tid or 'nums' in tid for tid in target_ids):
                event['code_line'] = 11
        elif op == 'set' and 'prev2' in target_ids:
            event['code_line'] = 12
        elif op == 'set' and 'prev1' in target_ids:
            event['code_line'] = 13
        elif op == 'note':
            event['code_line'] = 11
        elif op == 'result':
            event['code_line'] = 14
        else:
            event['code_line'] = 11
    return trace
